<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Notification Preferences</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0f172a;
      --panel: #111827;
      --panel-soft: #1f2937;
      --text: #f8fafc;
      --muted: #cbd5e1;
      --accent: #8b5cf6;
      --accent-strong: #a78bfa;
      --border: #334155;
      --shadow: 0 24px 80px rgba(0, 0, 0, 0.42);
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      display: grid;
      place-items: center;
      padding: 2rem;
      background:
        radial-gradient(circle at top left, rgba(139, 92, 246, 0.3), transparent 34rem),
        radial-gradient(circle at bottom right, rgba(14, 165, 233, 0.16), transparent 28rem),
        var(--bg);
      color: var(--text);
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      line-height: 1.5;
    }

    .app-shell {
      width: min(100%, 34rem);
    }

    .card {
      padding: clamp(1.5rem, 5vw, 2.5rem);
      border: 1px solid rgba(148, 163, 184, 0.22);
      border-radius: 1.5rem;
      background: linear-gradient(145deg, rgba(17, 24, 39, 0.94), rgba(15, 23, 42, 0.96));
      box-shadow: var(--shadow);
      backdrop-filter: blur(18px);
    }

    .eyebrow {
      margin: 0 0 0.5rem;
      color: var(--accent-strong);
      font-size: 0.8rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0 0 0.75rem;
      font-size: clamp(1.75rem, 6vw, 2.45rem);
      line-height: 1.1;
    }

    .intro {
      margin: 0 0 2rem;
      color: var(--muted);
    }

    .form-field {
      margin: 0 0 1.5rem;
    }

    .form-field fieldset {
      min-width: 0;
      margin: 0;
      padding: 0;
      border: 0;
    }

    .question {
      margin: 0 0 1rem;
      color: var(--text);
      font-size: 1.1rem;
      font-weight: 700;
    }

    .radio-options {
      display: grid;
      gap: 0.85rem;
    }

    .radio-option {
      display: flex;
      align-items: center;
      gap: 0.85rem;
      padding: 1rem;
      border: 1px solid var(--border);
      border-radius: 1rem;
      background: rgba(31, 41, 55, 0.62);
      color: var(--text);
      cursor: pointer;
      transition: border-color 160ms ease, background 160ms ease, transform 160ms ease;
    }

    .radio-option:hover {
      border-color: rgba(167, 139, 250, 0.75);
      background: rgba(55, 65, 81, 0.72);
      transform: translateY(-1px);
    }

    .radio-option input {
      width: 1.2rem;
      height: 1.2rem;
      margin: 0;
      accent-color: var(--accent);
      flex: 0 0 auto;
    }

    .radio-option:has(input:checked) {
      border-color: var(--accent-strong);
      background: rgba(139, 92, 246, 0.2);
    }

    .radio-option:has(input:focus-visible) {
      outline: 3px solid rgba(167, 139, 250, 0.42);
      outline-offset: 3px;
    }

    .submit-button {
      width: 100%;
      min-height: 3rem;
      border: 0;
      border-radius: 999px;
      background: linear-gradient(135deg, var(--accent), #06b6d4);
      color: white;
      font: inherit;
      font-weight: 800;
      cursor: pointer;
      box-shadow: 0 12px 36px rgba(139, 92, 246, 0.32);
      transition: filter 160ms ease, transform 160ms ease;
    }

    .submit-button:hover {
      filter: brightness(1.08);
      transform: translateY(-1px);
    }

    .submit-button:focus-visible {
      outline: 3px solid rgba(248, 250, 252, 0.78);
      outline-offset: 4px;
    }
  </style>
</head>
<body>
  <div id="root"></div>

  <script>
    const notificationChoices = [
      { id: "notification-email", value: "email", label: "Email" },
      { id: "notification-sms", value: "sms", label: "SMS" },
      { id: "notification-push", value: "push", label: "Push Notifications" }
    ];

    function RadioOption({ id, value, label }) {
      return `
        <label class="radio-option" for="${id}">
          <input id="${id}" type="radio" name="notificationPreference" value="${value}" required>
          <span>${label}</span>
        </label>
      `;
    }

    function NotificationPreferenceForm() {
      const options = notificationChoices.map(RadioOption).join("");

      return `
        <main class="app-shell">
          <section class="card" aria-labelledby="page-title">
            <p class="eyebrow">Preferences</p>
            <h1 id="page-title">Choose your notification style</h1>
            <p class="intro">Select the single option that works best for important account updates.</p>

            <form>
              <div class="form-field">
                <fieldset>
                  <legend class="question">How do you prefer to receive notifications?</legend>
                  <div class="radio-options">
                    ${options}
                  </div>
                </fieldset>
              </div>

              <button class="submit-button" type="submit">Submit preference</button>
            </form>
          </section>
        </main>
      `;
    }

    function App() {
      return NotificationPreferenceForm();
    }

    document.getElementById("root").innerHTML = App();
  </script>
</body>
</html>
